/**
 * Test custom bundle mechanism of jsr 303
 *
 * https://issues.apache.org/jira/browse/WICKET-5654
 *
 * @throws Exception
 */
@Test
public void testBundleKeysResolution() throws Exception {
    ValidatorFactory factory = Validation.buildDefaultValidatorFactory();
    Validator validator = factory.getValidator();
    DefaultViolationTranslator translator = new DefaultViolationTranslator();
    // test with a too short password
    BeanWithPassword bean = new BeanWithPassword("short");
    Set<ConstraintViolation<BeanWithPassword>> constraintViolations = validator.validate(bean);
    assertEquals(1, constraintViolations.size());
    @SuppressWarnings("unchecked")
    ConstraintViolation<BeanWithPassword> shortViolation = (ConstraintViolation<BeanWithPassword>) constraintViolations.toArray()[0];
    ValidationError error = translator.convert(shortViolation);
    checkErrorBundleKeys(error, DEFAULT_BUNDLE_KEY + ".String", DEFAULT_BUNDLE_KEY);
    // test with a password containing non-word chars
    bean.setPassword("notWord&%$£");
    constraintViolations = validator.validate(bean);
    assertEquals(1, constraintViolations.size());
    @SuppressWarnings("unchecked")
    ConstraintViolation<BeanWithPassword> nonWordviolation = (ConstraintViolation<BeanWithPassword>) constraintViolations.toArray()[0];
    error = translator.convert(nonWordviolation);
    checkErrorBundleKeys(error, CUSTOM_BUNDLE_KEY + ".String", CUSTOM_BUNDLE_KEY, DEFAULT_BUNDLE_KEY + ".String", DEFAULT_BUNDLE_KEY);
    // test with a valid password
    bean.setPassword("aValidPassword1234");
    constraintViolations = validator.validate(bean);
    assertEquals(0, constraintViolations.size());
}

@Test
public void testNotNullFields() {
    TestPage page = scope.getTester().startPage(TestPage.class);
    // no group
    assertTrue(page.input1.isRequired());
    assertFalse(page.input2.isRequired());
    assertFalse(page.input3.isRequired());
    assertFalse(page.input4.isRequired());
    // group1
    assertFalse(page.input5.isRequired());
    assertTrue(page.input6.isRequired());
    assertFalse(page.input7.isRequired());
    assertTrue(page.input8.isRequired());
    // group2
    assertFalse(page.input9.isRequired());
    assertFalse(page.input10.isRequired());
    assertTrue(page.input11.isRequired());
    assertTrue(page.input12.isRequired());
    // group1+group2
    assertFalse(page.input13.isRequired());
    assertTrue(page.input14.isRequired());
    assertTrue(page.input15.isRequired());
    assertTrue(page.input16.isRequired());
    // group3
    assertFalse(page.input17.isRequired());
    assertFalse(page.input18.isRequired());
    assertFalse(page.input19.isRequired());
    assertFalse(page.input20.isRequired());
    assertTrue(page.input21.isRequired());
}

