 */
@Test
public void noCrypt() {
    // The NoCrypt implementation does not modify the string at all
    final ICrypt crypt = new NoCrypt();
    assertEquals("test", crypt.encryptUrlSafe("test"));
    assertEquals("test", crypt.decryptUrlSafe("test"));
}

