    MockPageWithLink mockPageWithLink = new MockPageWithLink();
    AbstractLink link = new AbstractLink("link") {

        private static final long serialVersionUID = 1L;

        @Override
        public IModel<?> getBody() {
            return Model.of(counter.getAndIncrement());
        }
    };
