    String elementBody = "<!-- someJS() ";
    assertFalse(filter.shouldWrapInCdata(elementBody));
    elementBody = "\n<!-- someJS() ";
    assertFalse(filter.shouldWrapInCdata(elementBody));
    elementBody = "  <!-- someJS() ";
    assertFalse(filter.shouldWrapInCdata(elementBody));
    elementBody = "<![CDATA[ someJS() ";
    assertFalse(filter.shouldWrapInCdata(elementBody));
    elementBody = "\n<![CDATA[ someJS() ";
    assertFalse(filter.shouldWrapInCdata(elementBody));
    elementBody = "  <![CDATA[ someJS() ";
    assertFalse(filter.shouldWrapInCdata(elementBody));
    elementBody = "/*<![CDATA[*/ someJS() ";
    assertFalse(filter.shouldWrapInCdata(elementBody));
    elementBody = "\n/*<![CDATA[ */ someJS() ";
