    assertEquals(null, KEY1.get(md));
    assertEquals("2", KEY2.get(md));
    assertEquals(null, KEY3.get(md));
    assertEquals(null, KEY4.get(md));
    md = KEY2.set(md, null);
    assertNull(md);
