    final byte[] expectedMessage = "some message".getBytes("UTF-8");
    final int offset = 1;
    final int length = 2;
    WebSocketBehaviorTestPage page = new WebSocketBehaviorTestPage(expectedMessage, offset, length);
    tester.startPage(page);
